package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class EnvironmentVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property environment of observed source ")
  void test_environment_v_o_builder() {
    Assertions.assertFalse(EnvironmentVO.nullValue().getEnvironment().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(EnvironmentVO.tryFrom(null).getEnvironment().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", EnvironmentVO.from("one").getEnvironment().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> EnvironmentVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", EnvironmentVO.from("one").toString());
  }
}
